    public static function obtenerModeloNominaxIdTipoNomina($idtiponomina, $idestructura, $criterio, $start = 0,$limit = 10000)
    {
        $where = (!empty($criterio)) ? " c.denominacion ilike '%" . $criterio . "%'" : ' c.denominacion is not null';
        //Devolviendo la cantidad total de los salarios especificos.
        return Doctrine_Query::create()
            ->from('ConfigEstructurarModelosNomina c')
            ->innerJoin('c.ConfigEstructuraModeloNominaEntidad ce')
            ->where('c.idtiponomina = ? and ce.idestructura = ? and ' . $where, array($idtiponomina, $idestructura))
            ->orderBy('c.orden ASC')
            ->limit($limit)
            ->offset($start)
            ->fetchArray();
    }

