               mod_nomina.dat_elaborarpagos.idelaborarpagos=$idElaborarPago";

        $mg = Doctrine_Manager::getInstance();
        $conn = $mg->getCurrentConnection();
        $r = $conn->fetchAll($sql);
        return $r;
    }

