    public static function obtenerCampoADevengar($id, $esconceptopagosalario)
    {
        //Devolviendo el listado de tipos de pago en forma de arreglo.
        return Doctrine_Query::create()
            ->select('cemn.idestructuramodelodomina as idestructuramodelodomina')
            ->from('ConfigEstructurarModelosNomina cemn')
            ->innerJoin('cemn.ConfigModeloNomina cmn')
            ->innerJoin('cmn.DatElaborarPagos dep')
            ->where('dep.idelaborarpagos = ? and cemn.esconceptopagosalario = ?', array($id, $esconceptopagosalario))
            ->fetchOne()
