    }

    public static function obtenerCampoADevengarEntidad($idelaborarpagos, $esconceptopagosalario, $identidad){
        $mg = Doctrine_Manager::getInstance();
        $conn = $mg->getCurrentConnection();
        $sql = "select en.idestructuramodelodomina
			from mod_nomina.conf_estructuramodelosnomina en
			inner join mod_nomina.conf_estructuramodelosnominaentidad ene on (ene.idestructuramodelodomina = en.idestructuramodelodomina)
			inner join mod_nomina.conf_modelonomina mn on (mn.idtiponomina = en.idtiponomina)
			inner join mod_nomina.dat_elaborarpagos ep on (ep.idtipopago = mn.idtipopago)
			where ep.idelaborarpagos = ? and en.esconceptopagosalario = ? and ene.idestructura = ?;";
        $r = $conn->fetchOne($sql, array($idelaborarpagos, $esconceptopagosalario,$identidad));
        return $r;
    }

