    public static function obtenerCampoTalonario($idelaborarpagos)
    {
        $idelaborarpagos = is_array($idelaborarpagos) ? implode(',', $idelaborarpagos) : $idelaborarpagos;
        $mg = Doctrine_Manager::getInstance();
        $conn = $mg->getCurrentConnection();
        $sql = "select cmn.idtiponomina,ntn.denominacion as tiponomina, en.idestructuramodelodomina, en.orden as ordenreporte, en.denominacion,en.idtipocampo,en.escampopersona
			from mod_nomina.conf_estructuramodelosnomina en
			inner join mod_nomina.conf_modelonomina cmn on (cmn.idtiponomina = en.idtiponomina)
			inner join mod_nomina.nom_tiponomina ntn on (ntn.idtiponomina = cmn.idtiponomina)
			inner join mod_nomina.dat_elaborarpagos dep on (dep.idtipopago = cmn.idtipopago)
			where dep.idelaborarpagos in ({$idelaborarpagos}) and en.talonario = 1 order by en.idtiponomina, en.orden ASC; ";
        return $conn->fetchAll($sql);
    }

    public static function obtenerCampoADevengarTalonario($idelaborarpagos, $esconceptopagosalario)
    {
        $idelaborarpagos = is_array($idelaborarpagos) ? implode(',', $idelaborarpagos) : $idelaborarpagos;
        $mg = Doctrine_Manager::getInstance();
        $conn = $mg->getCurrentConnection();
        $sql = "select cemn.idestructuramodelodomina
			from mod_nomina.conf_estructuramodelosnomina cemn
			inner join mod_nomina.conf_modelonomina cmn on (cmn.idtiponomina = cemn.idtiponomina)
			inner join mod_nomina.dat_elaborarpagos dep on (dep.idtipopago = cmn.idtipopago)
			inner join mod_nomina.nom_tiponomina ntn on (ntn.idtiponomina = cmn.idtiponomina and tipomoneda = '01')
			where dep.idelaborarpagos in ({$idelaborarpagos}) and cemn.esconceptopagosalario = ?; ";
        return $conn->fetchAll($sql, array($esconceptopagosalario));
    }

