    public static function obtenerOrdenDisponible($identidad, $idtiponomina)
    {
        $mg = Doctrine_Manager::getInstance();
        $conn = $mg->getCurrentConnection();
        $sql = "select MAX(cemn.orden) as orden, MAX(cemn.ordenreporte) as ordenreporte
			--from mod_nomina.conf_estructuramodelosnomina cemn
			--inner join mod_nomina.conf_estructuramodelosnominaentidad cemne on (cemne.idestructuramodelodomina = cemne.idestructuramodelodomina)
			from mod_nomina.conf_estructuramodelosnominaentidad cemne
			inner join mod_nomina.conf_estructuramodelosnomina cemn on (cemn.idestructuramodelodomina = cemne.idestructuramodelodomina)
			where cemne.idestructura = ? and cemn.idtiponomina = ? ";
        $r = $conn->fetchAll($sql, array($identidad, $idtiponomina));
        $r[0]['orden'] = !empty($r) ? $r[0]['orden'] + 1 : 1;
        $r[0]['ordenreporte'] = !empty($r) ? $r[0]['ordenreporte'] + 1 : 1;
        return $r[0];
    }

