    public static function obtenerCantidadConceptoPagoSalarioTipoNomina($idestructurarmodelosnomiona, $idtiponomina, $identidad, $accion)
    {
        $where = '';
        if($accion == 'Add'){
            $where = "where en.idtiponomina = ? and ene.idestructura = ? and esconceptopagosalario = 1";
        }else{
            $where = "where en.idtiponomina = ? and ene.idestructura = ? and en.idestructuramodelodomina <> {$idestructurarmodelosnomiona} and esconceptopagosalario = 1";
        }
        $mg = Doctrine_Manager::getInstance();
        $conn = $mg->getCurrentConnection();
        $sql = "select COUNT (en.idestructuramodelodomina) as cantidad
			from mod_nomina.conf_estructuramodelosnomina en
			inner join mod_nomina.conf_estructuramodelosnominaentidad ene on (ene.idestructuramodelodomina = en.idestructuramodelodomina)";
        $sql = $sql.$where.";";
        $r = $conn->fetchOne($sql, array($idtiponomina,$identidad));
        return $r;
    }

    public static function obtenerMesAcumulaSNC($idestructuramodelodomina)
    {

        return Doctrine_Query::create()->select('idmessnc')
            ->from('ConfigEstructurarModelosNomina')
            ->where('idestructuramodelodomina = ?', array($idestructuramodelodomina))
            ->fetchOne()
            ->idmessnc;
    }
}
